#' Histogram (Core, Python)
#'
#' 
#' @param data .
#' @param dep .
#' @param subject .
#' @param changebinwidth .
#' @param binwidth .
#' @param resultssubtitle .
#' @param enableOneSampleTest .
#' @param testValue .
#' @param conflevel .
#' @param showBins .
#' @param showCases .
#' @param showPlot .
#' @param centralityline .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descriptives} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$binning} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bins} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$meanTest} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$meanLimits} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cases} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$histogramPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pyjjhistostats <- function(
    data,
    dep = NULL,
    subject = NULL,
    changebinwidth = FALSE,
    binwidth = 1.1,
    resultssubtitle = FALSE,
    enableOneSampleTest = FALSE,
    testValue = 0,
    conflevel = 0.95,
    showBins = FALSE,
    showCases = FALSE,
    showPlot = TRUE,
    centralityline = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyjjhistostats requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(subject)) subject <- jmvcore::resolveQuo(jmvcore::enquo(subject))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(subject), subject, NULL))


    options <- pyjjhistostatsOptions$new(
        dep = dep,
        subject = subject,
        changebinwidth = changebinwidth,
        binwidth = binwidth,
        resultssubtitle = resultssubtitle,
        enableOneSampleTest = enableOneSampleTest,
        testValue = testValue,
        conflevel = conflevel,
        showBins = showBins,
        showCases = showCases,
        showPlot = showPlot,
        centralityline = centralityline,
        showConsole = showConsole)

    analysis <- pyjjhistostatsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

